class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}  # name -> vip bool
        self._tickets = {}    # id -> dict
        self._next_id = 1
        # open tickets, keyed by id, with insertion order as tiebreaker
        self._open = {}       # id -> insertion counter (preserves order)
        self._counter = 0

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Title must not be empty")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")
        if customer not in self._customers:
            # allow implicitly, treat as non-VIP
            self._customers[customer] = False
        tid = self._next_id
        self._next_id += 1
        self._tickets[tid] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "state": "open",
        }
        self._counter += 1
        self._open[tid] = self._counter
        return tid

    def _priority_key(self, tid: int):
        t = self._tickets[tid]
        vip = self._customers.get(t["customer"], False)
        # Lower tuple = handled first.
        # VIP first (0 vs 1), then priority rank: critical(0) < high(1) < normal(2)
        prio_rank = {"critical": 0, "high": 1, "normal": 2}[t["priority"]]
        return (0 if vip else 1, prio_rank, self._open[tid])

    def next_ticket(self) -> int | None:
        if not self._open:
            return None
        tid = min(self._open, key=self._priority_key)
        del self._open[tid]
        self._tickets[tid]["state"] = "in_progress"
        return tid

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(ticket_id)
        self._tickets[ticket_id]["state"] = "closed"
        self._open.pop(ticket_id, None)

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(ticket_id)
        t = self._tickets[ticket_id]
        if t["state"] == "closed":
            raise ValueError("Cannot reopen a closed ticket")
        if t["state"] == "open":
            return  # already in queue
        t["state"] = "open"
        self._counter += 1
        self._open[ticket_id] = self._counter
